package com.own.user.party.address.dto;
public class AddressCommand { private String recipientName,mobile,province,city,district,detail; private Boolean defaultAddress; public String getRecipientName(){return recipientName;} public void setRecipientName(String v){recipientName=v;} public String getMobile(){return mobile;} public void setMobile(String v){mobile=v;} public String getProvince(){return province;} public void setProvince(String v){province=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getDistrict(){return district;} public void setDistrict(String v){district=v;} public String getDetail(){return detail;} public void setDetail(String v){detail=v;} public Boolean getDefaultAddress(){return defaultAddress;} public void setDefaultAddress(Boolean v){defaultAddress=v;} }
